import{z as o,x as s,o as t,c as i,q as P,j as B,D as l,d as a,s as n,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"困惑度评测的陷阱","description":"","frontmatter":{"title":"困惑度评测的陷阱","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/perplexity-eval-pitfalls.md","filePath":"llm/perplexity-eval-pitfalls.md","lastUpdated":1791063341000}'),p={name:"llm/perplexity-eval-pitfalls.md"};function D(d,E,L,m,F,u){const A=s("Mermaid");return t(),i("div",null,[E[2]||(E[2]=P('<h1 id="困惑度评测的陷阱" tabindex="-1">困惑度评测的陷阱 <a class="header-anchor" href="#困惑度评测的陷阱" aria-label="Permalink to &quot;困惑度评测的陷阱&quot;">​</a></h1><div class="epigraph"><p>困惑度是词表与分词器上的交叉熵指数，不是「懂多少」的通用单位。换一套 BPE，同一个模型可以换一张完全不同的榜。</p><footer>—— 对照 Jelinek 的经典定义；分词器耦合见后续对数似然评测课</footer></div><p><a href="/llm/mt-bench">上一课</a>把评测方法学课序收在 MT-Bench 的多轮能力剖面：八类八十题、两轮对话，LLM 当裁判打十分制。本课打开「评测协议与裁判」，问单个数字怎么来：压缩报告里常把困惑度（perplexity, PPL）当「量化没把模型打坏」的证据，而 PPL 作为<strong>能力数字</strong>有哪些陷阱。缺口不是再推交叉熵，而是：发布声明若写成「PPL 更低所以更强」，仪器已经选错。后课对数似然对生成式评测默认你已知道 PPL 不能单独签发能力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PPL 是 \\(2^{H}\\) 或 \\(e^{H}\\)，其中 \\(H\\) 是每个 token 的平均负对数似然。它忠实于语言建模目标，因此对训练损失、数据域、<a href="/llm/bpe-merge-rule">分词器</a> 都敏感。换词表、换预分词、是否把标点粘在词上，都会改 token 数与每个 token 的难度，PPL 随之动，模型权重可以一动不动。跨模型比 PPL，等于在比两套不同的计数单位。</p><p><span class="marginnote">PPL 的直觉读法：「模型在每个分叉口平均犹豫多少个等价选项」。PPL=20 意思是模型每生成一个 token 时，像在约 20 个同样可能的候选里挑；越接近 1，模型越笃定。它是「困惑」的度量，不是「能力」的度量。</span></p><p>第二陷阱是域。在维基上低、在对话上高，只说明预训练域，不说明指令遵循或解题。第三陷阱是与生成质量脱节：Holtzman 等人已说明，低 PPL 的极大似然解码会退化成重复；用户要的是可接受的样本，不是测试集上的指数损失。</p><p><span class="marginnote">压缩与蒸馏课用 PPL 当<strong>同一分词器、同一验证集</strong>上的回归探针，这是合法的。非法的是拿它去横比不同词表的基座，或用它代理 MMLU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合法用法：固定 tokenizer、固定验证文档、固定是否含特殊符号，报告平均负对数似然（nats 或 bits/byte 比 PPL 更可移植）。bits/byte 把长度归一到字节，减轻词表宽度作弊。非法用法：在聊天模板打开的模型上对裸语料算 PPL；在指令模型上对预训练 holdout 报 PPL 并声称对齐没有损伤——模板本身就改了条件分布。</p><p>发布时若必须报 PPL，同时报：词表、字节级损失、验证域。能力声明改走任务评测。</p>',11)),(t(),B(r,null,{default:l(()=>[n(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%E5%99%A8%20A%20%2F%20B%22%5D%0A%20%20TOK%20--%3E%20NLL%5B%22token%20%E8%B4%9F%E5%AF%B9%E6%95%B0%E4%BC%BC%E7%84%B6%22%5D%0A%20%20NLL%20--%3E%20PPL%5B%22PPL%22%5D%0A%20%20TOK%20--%3E%20BB%5B%22bits%2Fbyte%22%5D%0A%20%20PPL%20--%3E%20BAD%5B%22%E8%B7%A8%E8%AF%8D%E8%A1%A8%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20BB%20--%3E%20OK%5B%22%E9%95%BF%E5%BA%A6%E5%8D%95%E4%BD%8D%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"softmax 在词表上归一。大词表把概率质量摊到更多原子上，每个 token 更「难」，但一段话的 token 更少；小词表相反。PPL 按 token 平均，奖励切得碎的系统。bits/byte 按底层 UTF-8 平均，比较的是对同一字节串的压缩率，更接近「这个模型对这份语料的编码效率」。",-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：同一段 100 字的中文，词表 A 切成 150 个 token，词表 B 切成 90 个。权重完全相同的模型，在 A 上每个 token 更好预测、PPL 显得低，在 B 上每个 token 更难、PPL 显得高——两个 PPL 之间没有任何可比性。bits/byte 把两边都除以同样的字节数，单位才对齐。")],-1)),E[6]||(E[6]=e("p",null,"PPL 与开放生成还隔着解码器：温度、截断、停止符都不进损失。损失好只约束教师强迫分布，不约束你实际画出的那一条路径。",-1)),E[7]||(E[7]=e("p",null,[e("span",{class:"marginnote"},"初学者容易以为算 PPL 时模型「像生成时那样」自己在写；实际是教师强制——每一步都喂标准答案的前缀。真实生成喂的是自己上一步的输出，条件一旦不同，两个数字衡量的就不是同一件事。")],-1)),E[8]||(E[8]=e("p",null,"「PPL 低却生成差」的链条怎么一环环接起来：",-1)),(t(),B(r,null,{default:l(()=>[n(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TF%5B%22%E8%AE%AD%E7%BB%83%E4%B8%8E%E8%AF%84%E6%B5%8B%EF%BC%9A%E6%95%99%E5%B8%88%E5%BC%BA%E5%88%B6%EF%BC%8C%E6%AF%8F%E6%AD%A5%E9%83%BD%E7%9C%8B%E6%AD%A3%E7%A1%AE%E5%89%8D%E7%BC%80%22%5D%20--%3E%20PPL%5B%22%E6%B5%8B%E8%AF%95%20PPL%20%E4%BD%8E%22%5D%0A%20%20PPL%20--%3E%20GEN%5B%22%E5%BC%80%E6%94%BE%E7%94%9F%E6%88%90%EF%BC%9A%E6%B2%A1%E6%9C%89%E6%AD%A3%E7%A1%AE%E5%89%8D%E7%BC%80%E5%8F%AF%E7%9C%8B%22%5D%0A%20%20GEN%20--%3E%20FEED%5B%22%E8%87%AA%E5%B7%B1%E9%87%87%E5%87%BA%E7%9A%84%20token%20%E8%A2%AB%E5%96%82%E5%9B%9E%E4%BD%9C%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20FEED%20--%3E%20DRIFT%5B%22%E4%B8%80%E6%AD%A5%E5%81%8F%E4%BA%86%EF%BC%8C%E5%90%8E%E9%9D%A2%E6%AD%A5%E6%AD%A5%E5%9C%A8%E5%81%8F%E7%A7%BB%E7%9A%84%E6%9D%A1%E4%BB%B6%E4%B8%8A%E9%A2%84%E6%B5%8B%22%5D%0A%20%20DRIFT%20--%3E%20DEG%5B%22%E9%87%8D%E5%A4%8D%E4%B8%8E%E9%80%80%E5%8C%96%EF%BC%9A%E4%BD%8E%20PPL%20%E6%8B%A6%E4%B8%8D%E4%BD%8F%22%5D%0A%20%20GEN%20--%3E%20DEC%5B%22%E6%B8%A9%E5%BA%A6%E3%80%81%E6%88%AA%E6%96%AD%E3%80%81%E5%81%9C%E6%AD%A2%E7%AC%A6%E7%AD%89%E8%A7%A3%E7%A0%81%E9%80%89%E6%8B%A9%22%5D%0A%20%20DEC%20--%3E%20DEG%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=e("h2",{id:"边界",tabindex:"-1"},[a("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),E[10]||(E[10]=e("p",null,"本课不废除验证损失。训练曲线、过拟合、量化退化，仍应看同一仪器上的 NLL。下一课把「看选项的对数似然」和「生成后再抽答案」拆开——那是另一类被 PPL 思维带偏的评测。",-1)),E[11]||(E[11]=e("h2",{id:"小结",tabindex:"-1"},[a("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[12]||(E[12]=e("ul",null,[e("li",null,"PPL 绑定词表与域，不能当跨模型能力单位。"),e("li",null,"同一分词器上的 NLL / bits/byte 才是压缩与回归探针。"),e("li",null,"生成质量还取决于解码，低 PPL 不阻止退化。"),e("li",null,"出处：Jelinek 困惑度传统；Holtzman 等关于极大似然解码退化；字节级损失的工程实践。")],-1))])}const f=o(p,[["render",D]]);export{b as __pageData,f as default};
